export function getMallowGumballErrorMessage(code: MallowGumballError): string {
  if (process.env['NODE_ENV'] !== 'production') {
    return (mallowGumballErrorMessages as Record<MallowGumballError, string>)[
      code
    ];
  }

  return 'Error message not available in production bundles.';
}

export function isMallowGumballError<
  TProgramErrorCode extends MallowGumballError,
>(
  error: unknown,
  transactionMessage: {
    instructions: Record<number, { programAddress: Address }>;
  },
  code?: TProgramErrorCode
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    MALLOW_GUMBALL_PROGRAM_ADDRESS,
    code
  );
}
